def card(task, wd):
    data = {'north': 37, 'south': 21, 'east': 12}
    spec = {'role': 'entity', 'unit': '1 dot = 1 clinic', 'count': sum(data.values()), 'cap': 600, 'draw_all_edges': False, 'ends_static': True, 'subject': 'clinics'}
    bad = {'role': 'decor', 'count': 2400, 'cap': 600, 'draw_all_edges': True, 'ends_static': False}
    rng = R(3)
    starts = rng.uniform(10, 230, (spec['count'], 2))
    cols, tg = ([], [])
    for ci, (kk, n) in enumerate(data.items()):
        for j in range(n):
            tg.append((30 + ci * 80 + j % 6 * 7, 120 - j // 6 * 7))
            cols.append(ci)
    tg = np.array(tg, dtype=float)
    frames = []
    for f in range(40):
        e = float(in_out_cubic(min(1, f / 30)))
        a = canvas(240, 130)
        for (x, y), c in zip(starts + (tg - starts) * e, cols):
            a[int(round(y)) - 2:int(round(y)) + 1, int(round(x)) - 2:int(round(x)) + 1] = (255, 200, 80)
        frames.append(a)
    vid = video(wd / 'meaning.mp4', frames, 30)
    fr = vread(vid, 240, 130)
    lab, n = label(fr[-1][..., 0] > 128)
    counts = [int(len(set(lab[:, 20 + i * 80:20 + i * 80 + 60][lab[:, 20 + i * 80:20 + i * 80 + 60] > 0].ravel()))) for i in range(3)]
    static = float(np.abs(fr[-1] - fr[-5]).max())
    jw(wd / 'spec.json', {'spec': spec, 'issues': lint_particles(spec), 'bad_issues': lint_particles(bad)})
    return ([check('good spec passes the meaning lint', lint_particles(spec) == [], lint_particles(spec), []), check('one dot per entity in each region', counts == list(data.values()), counts, list(data.values())), check('ends on a static frame', static < 2, static, '<2'), check('negative control: decorative dust spec is flagged (>=4 issues)', len(lint_particles(bad)) >= 4, len(lint_particles(bad)), '>=4')], [vid, wd / 'spec.json'])

def card(task, wd):
    W, H = (300, 160)
    nodes = {'A': (30, 80), 'B': (150, 30), 'C': (150, 130), 'D': (270, 80), 'E': (270, 10)}
    edges = [('A', 'B'), ('A', 'C'), ('B', 'D'), ('C', 'D'), ('B', 'E')]
    focus = {'A', 'B', 'D'}
    shown = [e for e in edges if e[0] in focus and e[1] in focus]
    paths = {e: resample_closed(np.array([nodes[e[0]], nodes[e[1]]]), 2) for e in shown}

    def point_at(e, u):
        p, q = (np.array(nodes[e[0]], float), np.array(nodes[e[1]], float))
        return p + (q - p) * u
    T = 0.6
    phases = {e: [0, 0.33, 0.66] for e in shown}
    TRAIL = 12

    def frame(t):
        a = canvas(W, H)
        for e in shown:
            for ph in phases[e]:
                for k in range(TRAIL):
                    u = ((t - k / 60) / T + ph) % 1
                    x, y = point_at(e, u)
                    disc(a, x, y, 2 if k == 0 else 1.2, (255, 210, 60), 'max', (1 - k / TRAIL) ** 1.5)
        return a
    ts = np.arange(0, 1.2, 1 / 30)
    vid = video(wd / 'routes.mp4', [frame(t) for t in ts])
    fr = vread(vid, W, H)
    e = ('A', 'B')
    pa, pb = (np.array(nodes['A'], float), np.array(nodes['B'], float))
    samp = [pa + (pb - pa) * s for s in np.linspace(0.02, 0.98, 200)]

    def head_u(f):
        v = [f[int(y), int(x)].sum() for x, y in samp]
        return np.linspace(0.02, 0.98, 200)[int(np.argmax(v))]

    def one(t, trail=TRAIL):
        a = canvas(W, H)
        for k in range(trail):
            x, y = point_at(e, (t - k / 60) / T % 1)
            disc(a, x, y, 2 if k == 0 else 1.2, (255, 0, 0), 'max', (1 - k / trail) ** 1.5 if k else 1)
        return a
    v1 = vread(video(wd / 'one.mp4', [one(t) for t in np.arange(0, 0.6, 1 / 30)]), W, H)

    def trail_len(f):
        v = np.array([f[int(y), int(x), 0] for x, y in samp])
        return int((v > 20).sum())
    tl_on = trail_len(v1[9])
    tl_off = trail_len(one(9 / 30, trail=1))
    us = [head_u(f) for f in v1]
    du = np.diff(us)
    period = 1 / float(np.median(du)) / 30
    trail_f = fr[10]
    lit_off_edges = 0
    for e2 in edges:
        if e2 not in shown:
            p, q = (np.array(nodes[e2[0]], float), np.array(nodes[e2[1]], float))
            mid = (p + q) / 2
            lit_off_edges += int(trail_f[int(mid[1]) - 3:int(mid[1]) + 3, int(mid[0]) - 3:int(mid[0]) + 3].max() > 30)
    f = fr[5]
    v = np.array([f[int(y), int(x)].sum() for x, y in samp])
    return ([check('dots move A -> B (direction)', float(np.median(du)) > 0, float(np.median(du)), '>0'), check('600 ms per traversal (measured)', abs(period - 0.6) < 0.05, period, 0.6), check('only focus-neighbourhood edges carry particles', lit_off_edges == 0, lit_off_edges, 0), check('fading trail measured behind the head (lit samples)', tl_on >= 8, tl_on, '>=8'), check('negative control: the same measurement on a trail-less dot', tl_off < 8, tl_off, '<8')], [vid])

def card(task, wd):
    fps, g = (30, 6.0)

    def tape(t):
        return t if t < 1 else 1.0 if t < 2 else t - 1
    ev = {'t': 0.4, 'x': 0.0, 'y': 0.0}
    vx, vy = (2.5, -4.0)
    scale = 40

    def pos(t):
        tau = max(0.0, tape(t) - ev['t'])
        return (160 + scale * (vx * tau), 60 + scale * (vy * tau + 0.5 * g * tau * tau))
    frames = []
    for n in range(int(2.6 * fps)):
        t = n / fps
        img = np.zeros((240, 320, 3))
        if tape(t) >= ev['t']:
            _disc(img, *pos(t), 2.5, (255, 0, 0))
        frames.append(img)
    vid = _video(wd / 'tape_sparks.mp4', frames, fps)
    v = fx.frames(vid, (320, 240))
    tr = _track(v, 0, 100)
    frozen = [tr[n] for n in range(int(1.05 * fps), int(1.95 * fps))]
    hang = max((math.hypot(a[0] - frozen[0][0], a[1] - frozen[0][1]) for a in frozen))
    play = [(tape(n / fps) - ev['t'], c[1]) for n, c in enumerate(tr) if c and n < fps and (tape(n / fps) > ev['t'] + 0.05)]
    gy, _, res = _quad_fit(np.array([a for a, _ in play]), np.array([b for _, b in play]))

    def pos_wall(t):
        tau = max(0.0, t - ev['t'])
        return (160 + scale * (vx * tau), 60 + scale * (vy * tau + 0.5 * g * tau * tau))
    wf = [pos_wall(n / fps) for n in range(int(1.05 * fps), int(1.95 * fps))]
    wall_move = max((math.hypot(a[0] - wf[0][0], a[1] - wf[0][1]) for a in wf))
    return ([check('sparks hang in the air while the tape is stopped', hang < 0.5, hang, '<0.5 px'), check('ballistic on tape time: recovered gravity', abs(gy - g * scale) / (g * scale) < 0.05, gy, g * scale), check('negative control: on wall-clock time the spark does not hang', wall_move > 0.5, wall_move, '>0.5')], [vid])
